export const getProject = (slug) => projects.find((p) => p.slug.toLowerCase() === String(slug).toLowerCase()) || null;

/** All screenshots, or a single placeholder when a project has none yet. */
export const shotsOf = (p) => (p.screenshots && p.screenshots.length
  ? p.screenshots
  : [{ src: p.thumb || '/IMG/umt-logo.png', caption: p.name, type: 'desktop' }]);
export const coverOf = (p) => shotsOf(p)[0];

/** Screens grouped by device: browser-framed (web / admin) and phone-framed (mobile). */
export const isMobileShot = (s) => s && s.type === 'mobile';
export const splitShots = (p) => {
  const all = shotsOf(p);
  return { web: all.filter((s) => !isMobileShot(s)), mobile: all.filter(isMobileShot) };
};

const has = (list, re) => (list || []).some((x) => re.test(String(x)));
/**
 * What the project was delivered as, for the device labels:
 *  app        native / installable mobile app (Android, iOS, "Mobile App", "Mobile Apps" category)
 *  mobileWeb  no app, but a responsive site with mobile screens
 *  web        web app / platform / admin panel
 *  site       plain business website (no web-app platform)
 */
export const deviceKinds = (p) => {
  const { web, mobile } = splitShots(p);
  const app = has(p.platforms, /android|ios|^mobile( app)?$/i) || has(p.category, /mobile/i);
  const site = has(p.category, /business website/i) && !has(p.category, /platform|commerce/i);
  return {
    app,
    mobileWeb: !app && (mobile.length > 0 || has(p.platforms, /mobile web/i)),
    web: !site && (web.length > 0 || has(p.platforms, /web|admin|panel/i)),
    site,
  };
};
